Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:bold;">Unit cell type</div>
<div style="display:flex;flex-direction:column;gap:3px;">
  <button id="btnSC" class="active">Simple cubic</button>
  <button id="btnBCC">Body-centered cubic</button>
