/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.62));
const key = new THREE.DirectionalLight(0xffffff, 0.85);
key.position.set(-1.5, 5, 5);
scene.add(key);
const fill = new THREE.DirectionalLight(0xffffff, 0.25);
fill.position.set(3, -2, -4);
scene.add(fill);

/* ── cube shell (green faces + black edges) ─────────────────────────────── */
function makeCellShell() {
  const g = new THREE.Group();
  const faces = [
    { c: 0xe2f0cd, o: 0.50, p: [0, H, 0], r: [-Math.PI / 2, 0, 0] },   // top
    { c: 0xe2f0cd, o: 0.45, p: [0, -H, 0], r: [Math.PI / 2, 0, 0] },   // bottom
    { c: 0xcfe6ab, o: 0.55, p: [0, 0, H], r: [0, 0, 0] },              // +Z
    { c: 0xa5cd72, o: 0.65, p: [0, 0, -H], r: [0, Math.PI, 0] },       // -Z
    { c: 0xa5cd72, o: 0.65, p: [H, 0, 0], r: [0, Math.PI / 2, 0] },    // +X
    { c: 0xcfe6ab, o: 0.55, p: [-H, 0, 0], r: [0, -Math.PI / 2, 0] },  // -X
  ];
  for (const f of faces) {
    const m = new THREE.Mesh(
      new THREE.PlaneGeometry(A, A),
      new THREE.MeshBasicMaterial({
        color: f.c, transparent: true, opacity: f.o,
        side: THREE.DoubleSide, depthWrite: false
      })
    );
    m.position.set(...f.p);
    m.rotation.set(...f.r);
    m.renderOrder = -1;
    g.add(m);
  }
  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(new THREE.BoxGeometry(A, A, A)),
    new THREE.LineBasicMaterial({ color: 0x000000 })
  );
  edges.renderOrder = 2;
  g.add(edges);
  return g;
}

/* ── shared geometry & positions ────────────────────────────────────────── */
const SPH = new THREE.SphereGeometry(1, 40, 28);
const CORNERS = [];
for (const x of [-H, H]) for (const y of [-H, H]) for (const z of [-H, H]) CORNERS.push([x, y, z]);
const FACES = [[H, 0, 0], [-H, 0, 0], [0, H, 0], [0, -H, 0], [0, 0, H], [0, 0, -H]];

const schem = new THREE.Group(); schem.position.y = SCHEM_Y; scene.add(schem);
const model = new THREE.Group(); model.position.y = MODEL_Y; scene.add(model);
schem.add(makeCellShell());
model.add(makeCellShell());

function mkSphere(parent, pos, color, specular, transparent) {
  const mesh = new THREE.Mesh(SPH, new THREE.MeshPhongMaterial({
    color, specular, shininess: 40, transparent: !!transparent, opacity: 1
  }));
  mesh.position.set(pos[0], pos[1], pos[2]);
  parent.add(mesh);
  return mesh;
}

/* schematic lattice dots */
const cornerDots = CORNERS.map(p => mkSphere(schem, p, 0x111111, 0x555555, false));
const bodyDot = mkSphere(schem, [0, 0, 0], 0xee2222, 0xff9999, true);
const faceDots = FACES.map(p => mkSphere(schem, p, 0xee2222, 0xff9999, true));
cornerDots.forEach(d => d.scale.setScalar(0.09));

/* space-filling atoms */
const cornerAtoms = CORNERS.map(p => mkSphere(model, p, 0x9a9a9a, 0xcccccc, false));
const bodyAtom = mkSphere(model, [0, 0, 0], 0xc8471f, 0xe8804f, true);
const faceAtoms = FACES.map(p => mkSphere(model, p, 0xc8471f, 0xe8804f, true));

/* highlight shell */
const highlight = new THREE.Mesh(SPH, new THREE.MeshBasicMaterial({
  color: 0xffcc00, side: THREE.BackSide, transparent: true, opacity: 0.95, depthWrite: false
}));
highlight.visible = false;
highlight.scale.setScalar(1e-4);
scene.add(highlight);

/* ── interaction registration ───────────────────────────────────────────── */
const clickable = [];
function tag(mesh, kind) {
  const info = {
    corner: {
      share: '1/8 atom', title: 'Corner atom — 1/8 of an atom',
      body: 'A corner lattice point is shared by the eight unit cells that meet at that corner, so only 1/8 of the atom belongs to this cell. Eight corners × 1/8 = 1 atom.'
    },
    face: {
      share: '1/2 atom', title: 'Face-centered atom — 1/2 of an atom',
      body: 'An atom at the center of a face is shared between the two cells on either side of that face, so it contributes 1/2. Six faces × 1/2 = 3 atoms, plus 1 from the corners = 4 for FCC.'
    },
    body: {
      share: '1 atom', title: 'Body-centered atom — 1 whole atom',
      body: 'The body-center atom lies entirely inside this cell, so it contributes 1 whole atom. With the corners: 8 × 1/8 + 1 = 2 atoms per BCC cell. It touches all eight corner atoms along the body diagonal.'
    }
  }[kind];
  mesh.userData.kind = kind;
  mesh.userData.share = info.share;
  clickable.push(mesh);
  registerInteractive(mesh, {
    title: info.title, body: info.body, tooltip: info.share + ' in this cell'
  });
}
cornerAtoms.forEach(m => tag(m, 'corner'));
cornerDots.forEach(m => tag(m, 'corner'));
faceAtoms.forEach(m => tag(m, 'face'));
faceDots.forEach(m => tag(m, 'face'));
tag(bodyAtom, 'body');
tag(bodyDot, 'body');

/* ── camera ─────────────────────────────────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.65
});
controls.minPolarAngle = THREE.MathUtils.degToRad(20);
controls.maxPolarAngle = THREE.MathUtils.degToRad(150);

/* ── labels ─────────────────────────────────────────────────────────────── */
addLabel('Lattice point locations', new THREE.Vector3(0, SCHEM_Y + 1.85, 0),
  { bold: true, fontSize: '16px' });
addLabel('Cubic unit cells', new THREE.Vector3(0, 1.05, 0),
  { bold: true, fontSize: '16px' });
const captionLbl = addLabel('Simple cubic', new THREE.Vector3(0, MODEL_Y - 2.55, 0),
  { bold: true, fontSize: '15px' });
const calloutLbl = addLabel('', new THREE.Vector3(0, 0, 0),
  { bold: true, fontSize: '13px', color: '#7a4b00', background: 'rgba(255,240,180,0.92)', offset: [0, -34] });
calloutLbl.div.style.visibility = 'hidden';

/* ── state ──────────────────────────────────────────────────────────────── */
const TOUCH_R = { SC: 1.0, BCC: A * Math.sqrt(3) / 4, FCC: A * Math.sqrt(2) / 4 };
const NAMES = { SC: 'Simple cubic', BCC: 'Body-centered cubic', FCC: 'Face-centered cubic' };
const FORMULA = {
  SC: '<b>Simple cubic</b><br>8 corners × 1/8 = <b>1 atom</b> per cell<br>Contact along cube <i>edges</i>: a = 2r',
  BCC: '<b>Body-centered cubic</b><br>8 × 1/8 + 1 = <b>2 atoms</b> per cell<br>Contact along <i>body diagonal</i>: r = a√3⁄4',
  FCC: '<b>Face-centered cubic</b><br>8 × 1/8 + 6 × 1/2 = <b>4 atoms</b> per cell<br>Contact along <i>face diagonals</i>: r = a√2⁄4'
};
const state = { type: 'SC', atomScale: 1 };
let curScale = 1, curR = TOUCH_R.SC, opBody = 0, opFace = 0;

const readout = document.getElementById('readout');
const btns = { SC: document.getElementById('btnSC'), BCC: document.getElementById('btnBCC'), FCC: document.getElementById('btnFCC') };

function setType(t) {
  state.type = t;
  for (const k in btns) btns[k].classList.toggle('active', k === t);
  readout.innerHTML = FORMULA[t];
  captionLbl.div.innerHTML = NAMES[t];
  clearHighlight();
}
for (const k in btns) btns[k].addEventListener('click', () => { stopPlay(); setType(k); });

const sld = document.getElementById('sldScale');
const valScale = document.getElementById('valScale');
sld.addEventListener('input', () => {
  stopPlay();
  state.atomScale = parseFloat(sld.value);
  valScale.textContent = state.atomScale.toFixed(2);
});

/* ── highlight / callout ────────────────────────────────────────────────── */
let highlighted = null;
function clearHighlight() {
  highlighted = null;
  highlight.visible = false;
  calloutLbl.div.style.visibility = 'hidden';
}
function setHighlight(mesh) {
  highlighted = mesh;
  calloutLbl.div.innerHTML = mesh.userData.share;
  calloutLbl.div.style.visibility = 'visible';
}
const myRay = new THREE.Raycaster();
const myPtr = new THREE.Vector2();
renderer.domElement.addEventListener('click', (e) => {
  const rect = renderer.domElement.getBoundingClientRect();
  myPtr.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  myPtr.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  myRay.setFromCamera(myPtr, camera);
  const hits = myRay.intersectObjects(clickable.filter(m => m.visible), false);
  if (hits.length) setHighlight(hits[0].object); else clearHighlight();
});

/* ── demo steps ─────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Simple cubic', narr: 'Lattice points sit only at the eight corners. The gray spheres touch along the cube edges, so a = 2r, and 8 × 1/8 = 1 atom per unit cell.', type: 'SC', s: 1 },
  { title: 'Body-centered cubic', narr: 'A single red lattice point appears at the body center. The orange atom touches all eight corner atoms along the body diagonal: 8 × 1/8 + 1 = 2 atoms per cell.', type: 'BCC', s: 1 },
  { title: 'Face-centered cubic', narr: 'Red points now occupy the center of every face. Each orange face atom is shared between two cells, so 8 × 1/8 + 6 × 1/2 = 4 atoms per cell; contact is along the face diagonals.', type: 'FCC', s: 1 },
  { title: 'Shrink the atoms', narr: 'Reducing the radius peels the space-filling model back to the bare lattice-point diagram — showing that the two rows of the figure are the same geometry.', type: 'FCC', s: 0.3 }
];
let stepIdx = 0, playing = false, playTimer = null;
const stepTitle = document.getElementById('stepTitle');
const stepNarr = document.getElementById('stepNarr');
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  setType(st.type);
  state.atomScale = st.s;
  sld.value = String(st.s);
  valScale.textContent = st.s.toFixed(2);
  stepTitle.textContent = (stepIdx + 1) + '/' + STEPS.length + ' · ' + st.title;
  stepNarr.textContent = st.narr;
}
function stopPlay() {
  playing = false;
  if (playTimer) { clearInterval(playTimer); playTimer = null; }
  document.getElementById('btnPlay').textContent = '▶ Play';
}
document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
document.getElementById('btnPlay').addEventListener('click', () => {
  if (playing) { stopPlay(); return; }
  playing = true;
  document.getElementById('btnPlay').textContent = '❚❚ Pause';
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => goToStep(stepIdx + 1), 3600);
});
goToStep(0);

/* ── per-frame tweening ─────────────────────────────────────────────────── */
function applyGroup(list, op, scale) {
  const vis = op > 0.02;
  for (const m of list) {
    m.visible = vis;
    m.material.opacity = Math.min(1, op);
    m.scale.setScalar(vis ? scale : 1e-4);
  }
}
let prevT = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const k = Math.min(1, (now - prevT) / 16 * 0.16);
  prevT = now;

  curScale += (state.atomScale - curScale) * k;
  curR += (TOUCH_R[state.type] - curR) * k;
  const tBody = state.type === 'BCC' ? 1 : 0;
  const tFace = state.type === 'FCC' ? 1 : 0;
  opBody += (tBody - opBody) * k;
  opFace += (tFace - opFace) * k;

  const rAtom = curR * curScale;
  for (const m of cornerAtoms) m.scale.setScalar(rAtom);
  applyGroup([bodyAtom], opBody, rAtom);
  applyGroup(faceAtoms, opFace, rAtom);
  applyGroup([bodyDot], opBody, 0.07);
  applyGroup(faceDots, opFace, 0.07);

  if (highlighted) {
    if (!highlighted.visible) { clearHighlight(); }
    else {
      highlighted.getWorldPosition(highlight.position);
      const s = highlighted.scale.x * 1.16 + 0.02;
      highlight.scale.setScalar(s);
      highlight.visible = true;
      calloutLbl.pos.copy(highlight.position);
    }
  }
}
tick();
