/* ── cube shell: translucent green faces + black edges drawn on top ─────── */
function makeShell(mats) {
  const g = new THREE.Group();
  const faces = [
    { c: 0xeaf4d8, o: 0.55, p: [0, H, 0], r: [-Math.PI / 2, 0, 0] },
