const calloutLbl = addLabel('', new THREE.Vector3(0, 0, 0), {
  bold: true, fontSize: '13px', color: '#7a4b00',
  background: 'rgba(255,240,180,0.94)', offset: [0, -34]
});
calloutLbl.div.style.visibility = 'hidden';

/* ── state & panel wiring ───────────────────────────────────────────────── */
const FORMULA = {
  ALL: '<b>Compare the three cubic cells</b><br>' +
    'Simple cubic — 1 atom/cell, contact along <i>edges</i> (a = 2r)<br>' +
    'Body-centered — 2 atoms/cell, contact along the <i>body diagonal</i> (r = a√3⁄4)<br>' +
    'Face-centered — 4 atoms/cell, contact along <i>face diagonals</i> (r = a√2⁄4)',
