// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC (one line per element) ──────────────────────────────────
 // cell faces (×6 per cube)   → PlaneGeometry(A,A) MeshBasic translucent greens, depthWrite:false, renderOrder -1
 // cell edges (per cube)      → LineSegments(EdgesGeometry(Box(A,A,A))) black, depthTest:false, renderOrder 20
 // corner lattice dots (×8)   → SphereGeometry(1) scaled 0.07  MeshPhong #111111
 // body lattice dot (BCC)     → SphereGeometry(1) scaled 0.062 MeshPhong #ee2222
 // face lattice dots (FCC ×6) → SphereGeometry(1) scaled 0.062 MeshPhong #ee2222
 // corner atoms (×8)          → SphereGeometry(1) scaled r     MeshPhong #9a9a9a spec #dddddd
 // body atom (BCC)            → SphereGeometry(1) scaled r     MeshPhong #c8471f spec #e8905f
 // face atoms (FCC ×6)        → SphereGeometry(1) scaled r     MeshPhong #c8471f
 // highlight shell            → SphereGeometry(1) BackSide yellow, depthWrite:false
 // labels                     → addLabel: 2 row titles, 3 captions, 1 click callout
 ────────────────────────────────────────────────────────────────────────── */

const A = 1.6, H = A / 2;
const SCHEM_Y = 3.0, MODEL_Y = -2.6;
const TYPES = ['SC', 'BCC', 'FCC'];
const COLX = { SC: -3.7, BCC: 0, FCC: 3.7 };
const TOUCH = { SC: A / 2, BCC: A * Math.sqrt(3) / 4, FCC: A * Math.sqrt(2) / 4 };
const NAMES = { SC: 'Simple cubic', BCC: 'Body-centered cubic', FCC: 'Face-centered cubic' };

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.60));
const key = new THREE.DirectionalLight(0xffffff, 0.85);
key.position.set(-2.5, 4.5, 5);
scene.add(key);
const fill = new THREE.DirectionalLight(0xffffff, 0.22);
fill.position.set(3, -2.5, -4);
scene.add(fill);

/* ── shared geometry ────────────────────────────────────────────────────── */
const SPH = new THREE.SphereGeometry(1, 40, 28);
const CORNERS = [];
for (const x of [-H, H]) for (const y of [-H, H]) for (const z of [-H, H]) CORNERS.push([x, y, z]);
const FACES = [[H, 0, 0], [-H, 0, 0], [0, H, 0], [0, -H, 0], [0, 0, H], [0, 0, -H]];

/* ── cube shell: translucent green faces + black edges drawn on top ─────── */
function makeShell(mats) {
  const g = new THREE.Group();
  const faces = [
    { c: 0xeaf4d8, o: 0.55, p: [0, H, 0], r: [-Math.PI / 2, 0, 0] },
    { c: 0xdcecc2, o: 0.45, p: [0, -H, 0], r: [Math.PI / 2, 0, 0] },
    { c: 0xd9ebb8, o: 0.55, p: [0, 0, H], r: [0, 0, 0] },
    { c: 0xd9ebb8, o: 0.55, p: [0, 0, -H], r: [0, Math.PI, 0] },
    { c: 0xa9cd78, o: 0.72, p: [H, 0, 0], r: [0, Math.PI / 2, 0] },
    { c: 0xc7e19c, o: 0.55, p: [-H, 0, 0], r: [0, -Math.PI / 2, 0] },
  ];
  for (const f of faces) {
    const mat = new THREE.MeshBasicMaterial({
      color: f.c, transparent: true, opacity: f.o,
      side: THREE.DoubleSide, depthWrite: false
    });
    const m = new THREE.Mesh(new THREE.PlaneGeometry(A, A), mat);
    m.position.set(...f.p);
    m.rotation.set(...f.r);
    m.renderOrder = -1;
    mats.push({ m: mat, o: f.o });
    g.add(m);
  }
  const eMat = new THREE.LineBasicMaterial({
    color: 0x000000, transparent: true, opacity: 1, depthTest: false
  });
  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(new THREE.BoxGeometry(A, A, A)), eMat);
  edges.renderOrder = 20;
  mats.push({ m: eMat, o: 1 });
  g.add(edges);
  return g;
}

/* ── spheres ────────────────────────────────────────────────────────────── */
const clickable = [];
const SHARE = {
  corner: {
    share: '1/8 atom', title: 'Corner atom — 1/8 of an atom',
    body: 'A corner lattice point is shared by the eight unit cells that meet there, so only 1/8 of that atom belongs to this cell. Eight corners × 1/8 = 1 atom.'
  },
  face: {
    share: '1/2 atom', title: 'Face-centered atom — 1/2 of an atom',
    body: 'An atom centered on a face is shared between the two cells on either side of that face, so it contributes 1/2. Six faces × 1/2 = 3, plus 1 from the corners = 4 atoms for FCC.'
  },
  body: {
    share: '1 atom', title: 'Body-centered atom — 1 whole atom',
    body: 'The body-center atom lies entirely inside this cell, so it contributes a whole atom: 8 × 1/8 + 1 = 2 atoms per BCC cell. It touches all eight corner atoms along the body diagonal.'
  }
};

function mkSphere(parent, pos, color, spec, radius, mats, type, kind, isAtom) {
  const mat = new THREE.MeshPhongMaterial({
    color, specular: spec, shininess: 45, transparent: true, opacity: 1
  });
  const mesh = new THREE.Mesh(SPH, mat);
  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.scale.setScalar(radius);
  mesh.userData = { r: radius, kind, type, isAtom: !!isAtom, share: SHARE[kind].share };
  parent.add(mesh);
  mats.push({ m: mat, o: 1 });
  clickable.push(mesh);
  registerInteractive(mesh, {
    title: NAMES[type] + ' · ' + SHARE[kind].title,
    body: SHARE[kind].body,
    tooltip: SHARE[kind].share + ' in this cell'
  });
  return mesh;
}

/* ── build the six panels (3 columns × 2 rows) ──────────────────────────── */
const col = {};
for (const t of TYPES) {
  const mats = [];
  const sg = new THREE.Group(); sg.position.set(COLX[t], SCHEM_Y, 0); scene.add(sg);
  const mg = new THREE.Group(); mg.position.set(COLX[t], MODEL_Y, 0); scene.add(mg);
  sg.add(makeShell(mats));
  mg.add(makeShell(mats));
  const atoms = [];
  for (const p of CORNERS) {
    mkSphere(sg, p, 0x111111, 0x444444, 0.07, mats, t, 'corner', false);
    atoms.push(mkSphere(mg, p, 0x9a9a9a, 0xdddddd, TOUCH[t], mats, t, 'corner', true));
  }
  if (t === 'BCC') {
    mkSphere(sg, [0, 0, 0], 0xee2222, 0xff8888, 0.062, mats, t, 'body', false);
    atoms.push(mkSphere(mg, [0, 0, 0], 0xc8471f, 0xe8905f, TOUCH[t], mats, t, 'body', true));
  }
  if (t === 'FCC') {
    for (const p of FACES) {
      mkSphere(sg, p, 0xee2222, 0xff8888, 0.062, mats, t, 'face', false);
      atoms.push(mkSphere(mg, p, 0xc8471f, 0xe8905f, TOUCH[t], mats, t, 'face', true));
    }
  }
  col[t] = { sg, mg, mats, atoms, dim: 1, dimT: 1 };
}

/* highlight shell */
const highlight = new THREE.Mesh(SPH, new THREE.MeshBasicMaterial({
  color: 0xffcc00, side: THREE.BackSide, transparent: true, opacity: 0.95, depthWrite: false
}));
highlight.visible = false;
highlight.scale.setScalar(1e-4);
scene.add(highlight);

/* ── camera: oblique (cabinet) projection, as printed ───────────────────── */
setCameraView({
  projection: 'oblique',
  obliqueAngleDeg: 40,
  depthScale: 0.5,
  target: [0, -0.1, 0],
  heightFraction: 0.82
});
const ZALL = camera.zoom;
controls.minPolarAngle = THREE.MathUtils.degToRad(25);
controls.maxPolarAngle = THREE.MathUtils.degToRad(150);

function frameView(mode) {
  if (mode === 'ALL') {
    setCameraView({
      projection: 'oblique', obliqueAngleDeg: 40, depthScale: 0.5,
      target: [0, -0.1, 0], zoom: ZALL
    });
  } else {
    setCameraView({
      projection: 'oblique', obliqueAngleDeg: 40, depthScale: 0.5,
      target: [COLX[mode], -0.1, 0], zoom: ZALL * 1.12
    });
